import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.S3ClientBuilder;

/**
 * The processor's only S3 client, and the reader that uses it. Credentials come from the SDK's default chain, which
 * finds the IRSA role in AWS, so no keys are in the config.
 */
@Configuration(proxyBeanMethods = false)
public class S3StorageConfig {

    @Bean
    S3Client s3Client(ProcessorProperties properties) {
        S3ClientBuilder builder = S3Client.builder().region(Region.of(properties.aws().region()));
        if (properties.aws().endpointOverride() != null) {
            // A LocalStack host such as a compose service name doesn't resolve with the bucket as a subdomain.
            builder.endpointOverride(properties.aws().endpointOverride()).forcePathStyle(true);
        }
        return builder.build();
    }

    @Bean
    ObjectMetadataReader objectMetadataReader(S3Client s3, ProcessorProperties properties) {
        return new S3ObjectMetadataReader(s3, properties.storage().bucket());
    }
}

